:root {
  --bg: #1a1c2c;
  --card: #2d3348;
  --ink: #0f0f1a;
  --tomato: #ff6b6b;
  --gold: #ffd166;
  --cream: #f4e9d8;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
  font-family: "Courier New", Courier, monospace;
  color: var(--cream);
  background-color: var(--bg);
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.05) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.05) 1px, transparent 1px);
  background-size: 28px 28px;
}

.game-board {
  width: min(100%, 560px);
  background: var(--card);
  border: 4px solid var(--ink);
  box-shadow: 10px 10px 0 var(--ink);
  padding: clamp(1.25rem, 5vw, 2.5rem);
  text-align: center;
}

h1 {
  font-size: clamp(2rem, 7vw, 3.5rem);
  letter-spacing: 0.08em;
  color: var(--gold);
  text-shadow: 3px 3px 0 var(--ink);
  text-transform: uppercase;
  margin-bottom: 1rem;
}

.mode-label {
  font-size: 1.35rem;
  font-weight: bold;
  color: var(--tomato);
  text-shadow: 2px 2px 0 var(--ink);
  margin-bottom: 1.5rem;
}

.countdown {
  font-size: clamp(4rem, 18vw, 7.5rem);
  line-height: 1;
  font-weight: bold;
  color: var(--cream);
  background: var(--bg);
  border: 4px solid var(--ink);
  box-shadow: inset 0 0 0 4px rgba(0, 0, 0, 0.25), 0 6px 0 var(--ink);
  padding: 1rem 0.5rem;
  margin-bottom: 1.25rem;
  letter-spacing: 0.05em;
  text-shadow: 4px 4px 0 var(--ink);
  image-rendering: pixelated;
}

.status {
  min-height: 1.6em;
  font-size: 1.1rem;
  color: var(--cream);
  margin-bottom: 1.5rem;
}

.controls {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  justify-content: center;
}

.button {
  font: inherit;
  font-size: 1.3rem;
  font-weight: bold;
  padding: 0.85rem 1.6rem;
  min-height: 48px;
  border: 4px solid var(--ink);
  border-radius: 0;
  cursor: pointer;
  background: var(--tomato);
  color: var(--ink);
  box-shadow: 0 5px 0 var(--ink);
  transition: transform 0.08s ease, box-shadow 0.08s ease, background-color 0.15s ease, filter 0.15s ease;
}

.button.secondary {
  background: var(--gold);
}

.button:hover {
  filter: brightness(1.1);
}

.button:focus-visible {
  outline: 4px solid var(--cream);
  outline-offset: 4px;
}

.button:active {
  transform: translateY(5px);
  box-shadow: 0 0 0 var(--ink);
}

@media (max-width: 400px) {
  .game-board {
    padding: 1rem;
    box-shadow: 6px 6px 0 var(--ink);
  }

  .button {
    width: 100%;
  }
}

(function () {
  "use strict";

  const WORK_SECONDS = 25 * 60;
  const BREAK_SECONDS = 5 * 60;

  const startPauseButton = document.getElementById("start-pause");
  const resetButton = document.getElementById("reset");
  const countdownDisplay = document.getElementById("countdown");
  const modeLabel = document.getElementById("mode-label");
  const statusLabel = document.getElementById("status");

  let isWork = true;
  let timeLeft = WORK_SECONDS;
  let timerId = null;
  let isRunning = false;

  function formatTime(totalSeconds) {
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;
    return String(minutes).padStart(2, "0") + ":" + String(seconds).padStart(2, "0");
  }

  function updateDisplay() {
    const formatted = formatTime(timeLeft);
    countdownDisplay.textContent = formatted;
    modeLabel.textContent = isWork ? "Work mode" : "Break mode";
    document.title = formatted + " - " + (isWork ? "Work" : "Break") + " | Pixel Pomodoro";
  }

  function startTimer() {
    if (timerId !== null) return;

    timerId = setInterval(() => {
      timeLeft -= 1;
      if (timeLeft <= 0) {
        handleModeComplete();
      } else {
        updateDisplay();
      }
    }, 1000);
  }

  function pauseTimer() {
    if (timerId !== null) {
      clearInterval(timerId);
      timerId = null;
    }
  }

  function handleModeComplete() {
    if (isWork) {
      statusLabel.textContent = "Work session complete! Take a break.";
      isWork = false;
      timeLeft = BREAK_SECONDS;
    } else {
      statusLabel.textContent = "Break complete! Back to work.";
      isWork = true;
      timeLeft = WORK_SECONDS;
    }
    updateDisplay();
  }

  function toggleTimer() {
    if (isRunning) {
      pauseTimer();
      isRunning = false;
      startPauseButton.textContent = "Start";
      startPauseButton.setAttribute("aria-label", "Start timer");
      statusLabel.textContent = "Paused.";
    } else {
      startTimer();
      isRunning = true;
      startPauseButton.textContent = "Pause";
      startPauseButton.setAttribute("aria-label", "Pause timer");
      statusLabel.textContent = "";
    }
  }

  function resetTimer() {
    pauseTimer();
    isRunning = false;
    isWork = true;
    timeLeft = WORK_SECONDS;
    startPauseButton.textContent = "Start";
    startPauseButton.setAttribute("aria-label", "Start timer");
    statusLabel.textContent = "Timer reset.";
    updateDisplay();
  }

  startPauseButton.addEventListener("click", toggleTimer);
  resetButton.addEventListener("click", resetTimer);

  updateDisplay();
})();
